function [r] = head_frame(z)
%HEAD_FRAME  The body to head rotation (rows x, y, z) of a head whose boresight is z (body).
%   z: real[1][3] (passed a plain number)
%   returns r: real[1][3][3] (passed a plain number)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    r = zeros(3, 3);
    zu = asils.models.facets.unit_or_zero(z);
    x = asils.pc.cross_(zu, [0; 0; 1]);
    if (sqrt(x(1)*x(1) + x(2)*x(2) + x(3)*x(3)) < 0.000001)
        x = asils.pc.cross_(zu, [1; 0; 0]);
    end
    xu = asils.models.facets.unit_or_zero(x);
    yu = [zu(2)*xu(3) - zu(3)*xu(2); zu(3)*xu(1) - zu(1)*xu(3); zu(1)*xu(2) - zu(2)*xu(1)];
    r = [(xu).'; (yu).'; (zu).'];
end
